  1→import { useState } from "react";
  2→import { Badge } from "@/components/ui/badge";
  3→import { Button } from "@/components/ui/button";
  4→import { Separator } from "@/components/ui/separator";
  5→import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
  6→import { ScrollArea } from "@/components/ui/scroll-area";
  7→import { Phone, Mail, FileText, Archive, MapPin, Download } from "lucide-react";
  8→import { toast } from "sonner";
  9→import type { Result } from "@/pages/Index";
 10→import type { HiringStage } from "@/hooks/useStageTracker";
 11→
 12→import CandidateSummary from "@/components/candidate/CandidateSummary";
 13→import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
 14→import ExperiencePanel from "@/components/candidate/ExperiencePanel";
 15→import EducationPanel from "@/components/candidate/EducationPanel";
 16→import JDAlignedPanel from "@/components/candidate/JDAlignedPanel";
 17→import StrengthsGapsPanel from "@/components/candidate/StrengthsGapsPanel";
 18→import InterviewQuestionsPanel from "@/components/candidate/InterviewQuestionsPanel";
 19→import StageTracker from "@/components/candidate/StageTracker";
 20→import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
 21→
 22→interface CandidateDetailSheetProps {
 23→  result: Result | null;
 24→  isOpen: boolean;
 25→  onClose: () => void;
 26→  jobId?: string | null;
 27→  jobTitle?: string | null;
 28→  formatCandidateName: (filename: string) => string;
 29→  onDownload: (filePath: string, filename: string) => void;
 30→  onDismiss: (resumeId: string) => void;
 31→  currentStage?: HiringStage | null;
 32→  stageUpdatedAt?: string | null;
 33→  onStageChange?: (resumeId: string, stage: HiringStage) => void;
 34→}
 35→
 36→const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
 37→  if (score >= 70) return { label: "Strong", variant: "success" };
 38→  if (score >= 40) return { label: "Good", variant: "warning" };
 39→  return { label: "Weak", variant: "destructive" };
 40→};
 41→
 42→const CandidateDetailSheet = ({
 43→  result: r,
 44→  isOpen,
 45→  onClose,
 46→  jobId,
 47→  jobTitle,
 48→  formatCandidateName,
 49→  onDownload,
 50→  onDismiss,
 51→  currentStage,
 52→  stageUpdatedAt,
 53→  onStageChange,
 54→}: CandidateDetailSheetProps) => {
 55→  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
 56→
 57→  if (!r) return null;
 58→
 59→  const strength = getStrengthLabel(r.overall_score);
 60→  const candidateName = r.candidate_name || formatCandidateName(r.filename);
 61→
 62→  return (
 63→    <>
 64→      <Sheet open={isOpen} onOpenChange={(open) => { if (!open) onClose(); }}>
 65→        <SheetContent side="right" className="sm:max-w-2xl w-full p-0 flex flex-col gap-0">
 66→          {/* Header */}
 67→          <SheetHeader className="px-6 pt-6 pb-0 shrink-0 space-y-0">
 68→            <div className="flex items-start justify-between gap-4 pr-6">
 69→              <div className="min-w-0">
 70→                <SheetTitle className="text-lg truncate">{candidateName}</SheetTitle>
 71→                {(r.candidate_location || r.candidate_email) && (
 72→                  <div className="flex items-center gap-2 mt-1 flex-wrap">
 73→                    {r.candidate_location && (
 74→                      <span className="flex items-center gap-1 text-xs text-muted-foreground">
 75→                        <MapPin className="h-3 w-3" /> {r.candidate_location}
 76→                      </span>
 77→                    )}
 78→                    {r.candidate_email && (
 79→                      <span className="text-xs text-muted-foreground">{r.candidate_email}</span>
 80→                    )}
 81→                  </div>
 82→                )}
 83→              </div>
 84→            </div>
 85→          </SheetHeader>
 86→
 87→          {/* Score bar + actions */}
 88→          <div className="px-6 py-3 flex items-center gap-3 flex-wrap shrink-0">
 89→            <div className="flex items-center gap-2.5">
 90→              <div>
 91→                <span className="text-xs text-muted-foreground block">Overall Match</span>
 92→                <span className="text-2xl font-semibold tabular-nums text-foreground">{r.overall_score?.toFixed(0)}%</span>
 93→              </div>
 94→              <Badge variant={strength.variant}>{strength.label}</Badge>
 95→              {r.scoring_version === "heuristic" && <Badge variant="secondary">Quick</Badge>}
 96→            </div>
 97→
 98→            <Separator orientation="vertical" className="h-5 hidden sm:block" />
 99→
100→            <div className="flex items-center gap-1.5">
101→              {r.candidate_phone && (
102→                <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
103→                  onClick={() => { navigator.clipboard.writeText(r.candidate_phone!); toast.success("Phone copied!"); }}>
104→                  <Phone className="h-3 w-3" /> Call
105→                </Button>
106→              )}
107→              {r.candidate_email && (
108→                <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
109→                  onClick={() => setEmailDialogOpen(true)}>
110→                  <Mail className="h-3 w-3" /> Email
111→                </Button>
112→              )}
113→              {r.file_path && (
114→                <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
115→                  onClick={() => onDownload(r.file_path!, r.filename)}>
116→                  <Download className="h-3 w-3" /> Resume
117→                </Button>
118→              )}
119→              <Button variant="ghost" size="icon" className="h-8 w-8 text-muted-foreground hover:text-destructive"
120→                onClick={() => { onDismiss(r.resume_id); onClose(); }}>
121→                <Archive className="h-3.5 w-3.5" />
122→              </Button>
123→            </div>
124→          </div>
125→
126→          <Separator />
127→
128→          {/* Scrollable panels */}
129→          <div className="relative flex-1 min-h-0">
130→          <ScrollArea className="h-full">
131→            <div className="px-6 py-5 space-y-5">
132→              <CandidateSummary result={r} />
133→
134→              {onStageChange && (
135→                <StageTracker
136→                  currentStage={currentStage || "applied"}
137→                  updatedAt={stageUpdatedAt}
138→                  onStageChange={(stage) => onStageChange(r.resume_id, stage)}
139→                />
140→              )}
141→
142→              <StrengthsGapsPanel result={r} />
143→
144→              <div className="space-y-4">
145→                <SkillsDetailPanel result={r} />
146→                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
147→                  <ExperiencePanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves as string[]} />
148→                  <EducationPanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves} missingMustHaves={r.missing_must_haves} />
149→                </div>
150→              </div>
151→
152→              <JDAlignedPanel result={r} />
153→
154→              <InterviewQuestionsPanel result={r} />
155→            </div>
156→          </ScrollArea>
157→          <div className="absolute bottom-0 left-0 right-0 h-8 bg-gradient-to-t from-background to-transparent pointer-events-none" />
158→          </div>
159→        </SheetContent>
160→      </Sheet>
161→
162→      {r.candidate_email && (
163→        <EmailOutreachDialog
164→          open={emailDialogOpen}
165→          onOpenChange={setEmailDialogOpen}
166→          candidateName={candidateName}
167→          candidateEmail={r.candidate_email}
168→          jobTitle={jobTitle || "Open Position"}
169→          matchScore={Math.round(r.overall_score ?? 0)}
170→          resumeId={r.resume_id}
171→          jobId={jobId || ""}
172→        />
173→      )}
174→    </>
175→  );
176→};
177→
178→export default CandidateDetailSheet;
