  1→import { CheckCircle2, XCircle } from "lucide-react";
  2→import { Card, CardContent, CardHeader } from "@/components/ui/card";
  3→import { Badge } from "@/components/ui/badge";
  4→import type { Result } from "@/pages/Index";
  5→
  6→interface JDAlignedPanelProps {
  7→  result: Result;
  8→}
  9→
 10→type RecLevel = "success" | "secondary" | "warning" | "destructive";
 11→
 12→const getRecommendation = (score: number, hardFit: boolean | undefined, isHeuristic: boolean): { text: string; label: string; variant: RecLevel } => {
 13→  if (isHeuristic) return { text: "Needs full AI scoring for reliable recommendation", label: "Pending", variant: "warning" };
 14→  if (score >= 70 && hardFit !== false) return { text: "Strong core fit, gaps are learnable", label: "Shortlist", variant: "success" };
 15→  if (score >= 50 && hardFit !== false) return { text: "Decent match, review before interview", label: "Consider", variant: "secondary" };
 16→  if (score >= 40) return { text: "Has strengths but missing critical items", label: "Review", variant: "warning" };
 17→  return { text: "Significant gaps for this role", label: "Pass", variant: "destructive" };
 18→};
 19→
 20→const JDAlignedPanel = ({ result: r }: JDAlignedPanelProps) => {
 21→  const matched = Array.isArray(r.matched_must_haves) ? r.matched_must_haves.map(String) : [];
 22→  const missing = Array.isArray(r.missing_must_haves) ? r.missing_must_haves.map(String) : [];
 23→  const strengths = Array.isArray(r.strengths_json) ? r.strengths_json.map(String) : [];
 24→  const gaps = Array.isArray(r.gaps_json) ? r.gaps_json.map(String) : [];
 25→  const confidence = r.confidence ?? 0;
 26→  const interviewQs = Array.isArray(r.interview_questions) ? r.interview_questions.map(String) : [];
 27→  const isHeuristic = r.scoring_version === "heuristic";
 28→  const isInsufficient = r.scoring_version === "insufficient";
 29→
 30→  if (isInsufficient) return null;
 31→
 32→  const totalMustHave = matched.length + missing.length;
 33→  const mustHavePercent = totalMustHave > 0 ? Math.round((matched.length / totalMustHave) * 100) : 0;
 34→
 35→  const rawMatchedPref = r.explanation_json?.matched_preferred;
 36→  const matchedPreferred: string[] = Array.isArray(rawMatchedPref) ? rawMatchedPref.map(String)
 37→    : (isHeuristic ? [] : strengths.filter((s) => !matched.some((m) => s.toLowerCase().includes(m.toLowerCase()))));
 38→  const rawMissingPref = r.explanation_json?.missing_preferred;
 39→  const missingPreferred: string[] = Array.isArray(rawMissingPref) ? rawMissingPref.map(String)
 40→    : (isHeuristic ? [] : gaps.filter((g) => !missing.some((m) => g.toLowerCase().includes(m.toLowerCase()))));
 41→  const totalPreferred = matchedPreferred.length + missingPreferred.length;
 42→
 43→  const rec = getRecommendation(r.overall_score, r.hard_fit, isHeuristic);
 44→
 45→  if (totalMustHave === 0 && totalPreferred === 0 && !r.explanation_json?.why_ranked_here) return null;
 46→
 47→  return (
 48→    <Card>
 49→      <CardHeader className="pb-3 px-5 pt-4 flex-row items-center justify-between gap-3 space-y-0 flex-wrap">
 50→        <div className="flex items-center gap-3">
 51→          <h4 className="text-sm font-medium text-foreground">JD Alignment</h4>
 52→          {totalMustHave > 0 && (
 53→            <span className="text-sm text-muted-foreground tabular-nums">{mustHavePercent}% match</span>
 54→          )}
 55→        </div>
 56→        <div className="flex items-center gap-2">
 57→          <Badge variant={rec.variant}>{rec.label}</Badge>
 58→          {confidence > 0 && <Badge variant="outline" className="text-xs">{confidence}% confidence</Badge>}
 59→        </div>
 60→      </CardHeader>
 61→
 62→      <CardContent className="px-5 pb-5 pt-0">
 63→        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
 64→          {/* Must Have */}
 65→          {totalMustHave > 0 && (
 66→            <div className="space-y-3">
 67→              <div className="flex items-center gap-2">
 68→                <h5 className="text-xs font-medium text-muted-foreground">Must Have</h5>
 69→                <span className="text-xs text-muted-foreground/60">{matched.length}/{totalMustHave}</span>
 70→              </div>
 71→              <div className="space-y-2">
 72→                {matched.map((item, i) => (
 73→                  <div key={`m-${i}`} className="flex items-start gap-2 text-sm leading-snug">
 74→                    <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500 shrink-0 mt-0.5" />
 75→                    <span className="text-foreground">{item}</span>
 76→                  </div>
 77→                ))}
 78→                {missing.map((item, i) => (
 79→                  <div key={`x-${i}`} className="flex items-start gap-2 text-sm leading-snug">
 80→                    <XCircle className="h-3.5 w-3.5 text-red-400 shrink-0 mt-0.5" />
 81→                    <span className="text-muted-foreground/80">{item}</span>
 82→                  </div>
 83→                ))}
 84→              </div>
 85→            </div>
 86→          )}
 87→
 88→          {/* Preferred */}
 89→          {totalPreferred > 0 && (
 90→            <div className="space-y-3">
 91→              <div className="flex items-center gap-2">
 92→                <h5 className="text-xs font-medium text-muted-foreground">Preferred</h5>
 93→                <span className="text-xs text-muted-foreground/60">{matchedPreferred.length}/{totalPreferred}</span>
 94→              </div>
 95→              <div className="space-y-2">
 96→                {matchedPreferred.map((item, i) => (
 97→                  <div key={`pm-${i}`} className="flex items-start gap-2 text-sm leading-snug">
 98→                    <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500 shrink-0 mt-0.5" />
 99→                    <span className="text-foreground">{item}</span>
100→                  </div>
101→                ))}
102→                {missingPreferred.map((item, i) => (
103→                  <div key={`px-${i}`} className="flex items-start gap-2 text-sm leading-snug">
104→                    <XCircle className="h-3.5 w-3.5 text-red-400 shrink-0 mt-0.5" />
105→                    <span className="text-muted-foreground/80">{item}</span>
106→                  </div>
107→                ))}
108→              </div>
109→            </div>
110→          )}
111→
112→          {/* AI Insight */}
113→          <div className="space-y-3">
114→            <h5 className="text-xs font-medium text-muted-foreground">AI Insight</h5>
115→
116→            {r.explanation_json?.why_ranked_here && (
117→              <p className="text-sm text-muted-foreground leading-relaxed">{r.explanation_json.why_ranked_here}</p>
118→            )}
119→
120→            <p className="text-sm text-foreground leading-relaxed">{rec.text}</p>
121→
122→            {interviewQs.length > 0 && (
123→              <div className="pt-2 border-t border-border space-y-1">
124→                <h6 className="text-xs text-muted-foreground font-medium">Interview focus</h6>
125→                <p className="text-sm text-muted-foreground leading-relaxed">{interviewQs[0]}</p>
126→              </div>
127→            )}
128→
129→            {r.explanation_json?.key_tradeoffs && (
130→              <p className="text-sm text-muted-foreground/60 leading-relaxed">{r.explanation_json.key_tradeoffs}</p>
131→            )}
132→          </div>
133→        </div>
134→      </CardContent>
135→    </Card>
136→  );
137→};
