 37→/** Infer education level from degree name for icon + rank */
 38→type EduLevel = "doctorate" | "masters" | "bachelors" | "diploma" | "higher_secondary" | "secondary" | "other";
 39→
 40→const inferLevel = (degree: string): EduLevel => {
 41→  const d = degree.toLowerCase();
 42→  if (d.includes("phd") || d.includes("doctorate") || d.includes("d.phil")) return "doctorate";
 43→  if (d.includes("master") || d.includes("mba") || d.includes("m.sc") || d.includes("m.tech") || d.includes("m.e.") || d.includes("m.a.") || d.includes("msc") || d.includes("m.com")) return "masters";
 44→  if (d.includes("bachelor") || d.includes("b.sc") || d.includes("b.tech") || d.includes("b.e.") || d.includes("b.a.") || d.includes("bsc") || d.includes("b.com") || d.includes("bba") || d.includes("bca")) return "bachelors";
 45→  // Check secondary/higher_secondary BEFORE diploma — "High School Diploma" should be secondary, not diploma
 46→  if (d.includes("higher secondary") || d.includes("12th") || d.includes("hsc") || d.includes("intermediate") || d.includes("a-level") || d.includes("senior secondary")) return "higher_secondary";
 47→  if (d.includes("secondary") || d.includes("10th") || d.includes("ssc") || d.includes("o-level") || d.includes("high school") || d.includes("matriculation")) return "secondary";
 48→  if (d.includes("diploma") || d.includes("certificate") || d.includes("pgd") || d.includes("post graduate diploma")) return "diploma";
 49→  return "other";
 50→};
