 21→/* ── Date helpers ─────────────────────────────────────────── */
 22→
 23→/** Parse a date string into a rough Date (month-level) */
 24→const parseDate = (dateStr?: any): Date | null => {
 25→  if (dateStr == null) return null;
 26→  const s = String(dateStr).trim();
 27→
 28→  // Check "present/current"
 29→  if (/present|current|now/i.test(s)) return new Date();
 30→
 31→  // Try "MMM YYYY" or "MM/YYYY" or "YYYY"
 32→  const monthNames: Record<string, number> = {
 33→    jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5,
 34→    jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11,
 35→  };
 36→
 37→  // "Jan 2023", "January 2023", "Jun 2022"
 38→  const mmmYyyy = s.match(/([a-zA-Z]+)\s*(\d{4})/);
 39→  if (mmmYyyy) {
 40→    const mo = monthNames[mmmYyyy[1].slice(0, 3).toLowerCase()];
 41→    if (mo !== undefined) return new Date(parseInt(mmmYyyy[2]), mo);
 42→  }
 43→
 44→  // "2023-01", "01/2023"
 45→  const numDate = s.match(/(\d{1,2})[\/\-](\d{4})/);
 46→  if (numDate) return new Date(parseInt(numDate[2]), parseInt(numDate[1]) - 1);
 47→
 48→  // "2023"
 49→  const yearOnly = s.match(/\b(19|20)\d{2}\b/);
 50→  if (yearOnly) return new Date(parseInt(yearOnly[0]), 0);
 51→
 52→  return null;
 53→};
 54→
 55→const isCurrent = (dateStr?: any): boolean => {
 56→  if (dateStr == null) return false;
 57→  return /present|current|now/i.test(String(dateStr));
 58→};
 59→
 60→/** Compute months between two dates */
 61→const monthsBetween = (start: Date, end: Date): number => {
 62→  return Math.max(0, (end.getFullYear() - start.getFullYear()) * 12 + (end.getMonth() - start.getMonth()));
 63→};
 64→
 65→/** Format months as "X yrs Y mos" or "X mos" */
 66→const formatDuration = (months: number): string => {
 67→  if (months <= 0) return "";
 68→  const yrs = Math.floor(months / 12);
 69→  const mos = months % 12;
 70→  if (yrs === 0) return `${mos} mos`;
 71→  if (mos === 0) return `${yrs} yr${yrs !== 1 ? "s" : ""}`;
 72→  return `${yrs} yr${yrs !== 1 ? "s" : ""} ${mos} mos`;
 73→};
 74→
 75→/** Format date as "MMM YYYY" */
 76→const formatDate = (d: Date): string => {
 77→  const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
 78→  return `${months[d.getMonth()]} ${d.getFullYear()}`;
 79→};
 80→
 81→/** Get employment type label */
 82→const getEmpType = (role: Role): { label: string; cls: string } | null => {
 83→  const t = (role.employment_type || role.type || "").toLowerCase();
 84→  if (t.includes("intern")) return { label: "Internship", cls: "bg-purple-500/10 text-purple-600 border-purple-200 dark:text-purple-400 dark:border-purple-800" };
 85→  if (t.includes("contract") || t.includes("freelance")) return { label: "Contract", cls: "bg-amber-500/10 text-amber-600 border-amber-200 dark:text-amber-400 dark:border-amber-800" };
 86→  if (t.includes("part")) return { label: "Part-time", cls: "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800" };
 87→  if (t.includes("full") || t === "") return { label: "Full-time", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" };
 88→  return { label: t, cls: "bg-muted text-muted-foreground border-border" };
 89→};
 90→
 91→/** JD relevance tag */
 92→type RelevanceTag = "jd_relevant" | "partially_relevant" | "low_relevance";
 93→const RELEVANCE: Record<RelevanceTag, { label: string; cls: string }> = {
 94→  jd_relevant: { label: "JD Relevant", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" },
 95→  partially_relevant: { label: "Partially Relevant", cls: "bg-amber-500/10 text-amber-600 border-amber-200 dark:text-amber-400 dark:border-amber-800" },
 96→  low_relevance: { label: "Low Relevance", cls: "bg-muted/60 text-muted-foreground border-border" },
 97→};
 98→
 99→/* ── Component ────────────────────────────────────────────── */
100→
101→const ExperiencePanel = ({ parsedJson, matchedMustHaves }: ExperiencePanelProps) => {
102→  const [showDetail, setShowDetail] = useState(false);
103→  const rawRoles = parsedJson?.roles_with_dates ?? parsedJson?.experience;
104→  const roles: Role[] = Array.isArray(rawRoles) ? rawRoles : [];
105→  const matchedLower = Array.isArray(matchedMustHaves) ? matchedMustHaves.map((m) => String(m).toLowerCase()) : [];
106→
107→  // Parse dates for each role
108→  const parsed = roles.map((role) => {
109→    const startDate = parseDate(role.start);
110→    const endDate = parseDate(role.end) || (isCurrent(role.end) ? new Date() : null);
111→    const months = startDate && endDate ? monthsBetween(startDate, endDate) : 0;
112→    const empType = getEmpType(role);
113→    const isInternship = empType?.label === "Internship";
114→    const isCurrentRole = isCurrent(role.end);
115→
116→    // JD relevance: check if role title/description matches any must-have
117→    const combined = `${role.title || ""} ${role.description || ""} ${role.company || ""}`.toLowerCase();
118→    let relevance: RelevanceTag = "low_relevance";
119→    const fullMatch = matchedLower.some((m) => {
120→      const words = m.split(/\s+/).filter((w) => w.length > 3);
121→      return words.filter((w) => combined.includes(w)).length >= Math.max(1, Math.floor(words.length * 0.5));
122→    });
123→    if (fullMatch) relevance = "jd_relevant";
124→    else if (matchedLower.some((m) => {
125→      const words = m.split(/\s+/).filter((w) => w.length > 3);
126→      return words.some((w) => combined.includes(w));
127→    })) relevance = "partially_relevant";
128→
129→    return { ...role, startDate, endDate, months, empType, isInternship, isCurrentRole, relevance };
130→  });
131→
132→  // Stat pills
133→  const totalMonths = parsed.reduce((sum, r) => sum + r.months, 0);
134→  const fullTimeMonths = parsed.filter((r) => !r.isInternship).reduce((sum, r) => sum + r.months, 0);
135→  const internMonths = parsed.filter((r) => r.isInternship).reduce((sum, r) => sum + r.months, 0);
136→
137→  // Gap detection between consecutive roles
138→  const gaps: { afterIndex: number; months: number }[] = [];
139→  for (let i = 0; i < parsed.length - 1; i++) {
140→    const prev = parsed[i];
141→    const next = parsed[i + 1];
142→    if (prev.startDate && next.endDate) {
143→      const gapMonths = monthsBetween(next.endDate, prev.startDate);
144→      if (gapMonths >= 3) gaps.push({ afterIndex: i, months: gapMonths });
145→    }
146→  }
147→  const gapMap = new Map(gaps.map((g) => [g.afterIndex, g]));
148→
149→  return (
150→    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
151→      {/* Header with stat pills */}
152→      <div className="flex items-center gap-2 flex-wrap">
153→        <div className="w-6 h-6 rounded bg-purple-500/10 flex items-center justify-center">
154→          <Briefcase className="h-3.5 w-3.5 text-purple-500" />
155→        </div>
156→        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">Experience</h4>
157→        <div className="flex items-center gap-1 ml-auto flex-wrap">
158→          {totalMonths > 0 && (
159→            <Badge variant="outline" className="text-[11px] font-semibold">
160→              {formatDuration(totalMonths)} <span className="text-muted-foreground font-normal ml-0.5">Total</span>
161→            </Badge>
162→          )}
163→          {fullTimeMonths > 0 && internMonths > 0 && (
164→            <>
165→              <Badge variant="outline" className="text-[11px] bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800">
166→                {formatDuration(fullTimeMonths)} <span className="font-normal ml-0.5">Full-time</span>
167→              </Badge>
168→              <Badge variant="outline" className="text-[11px] bg-purple-500/10 text-purple-600 border-purple-200 dark:text-purple-400 dark:border-purple-800">
169→                {formatDuration(internMonths)} <span className="font-normal ml-0.5">Internship</span>
170→              </Badge>
171→            </>
172→          )}
173→        </div>
174→      </div>
175→
176→      {/* Roles timeline */}
177→      {parsed.length > 0 ? (
178→        <div className="space-y-0">
179→          {parsed.slice(0, showDetail ? undefined : 4).map((role, i) => {
180→            const gap = gapMap.get(i);
181→            const dotOpacity = "bg-muted-foreground/40";
182→            const rel = RELEVANCE[role.relevance];
183→
184→            return (
185→              <div key={i}>
186→                <div className="flex gap-2 py-1.5">
187→                  {/* Timeline dot + line */}
188→                  <div className="flex flex-col items-center mt-1.5">
189→                    <div className={`w-2 h-2 rounded-full shrink-0 ${dotOpacity}`} />
190→                    {i < parsed.length - 1 && <div className="w-px flex-1 bg-border mt-1" />}
191→                  </div>
192→
193→                  {/* Role content */}
194→                  <div className="flex-1 min-w-0 space-y-0.5">
195→                    <div className="flex items-center gap-1.5 flex-wrap">
196→                      <p className="text-xs font-semibold text-foreground leading-tight">
197→                        {role.title || "Untitled Role"}
198→                      </p>
199→                      {role.empType && (
200→                        <span className={`text-[11px] font-semibold uppercase px-1.5 py-0.5 rounded border ${role.empType.cls}`}>
201→                          {role.empType.label}
202→                        </span>
203→                      )}
204→                    </div>
205→                    {role.company && (
206→                      <p className="text-[11px] text-muted-foreground">{role.company}</p>
207→                    )}
208→                    <div className="flex items-center gap-1.5 flex-wrap">
209→                      {role.startDate && (
210→                        <span className="text-[11px] text-muted-foreground">
211→                          {formatDate(role.startDate)} – {role.isCurrentRole ? "Present" : role.endDate ? formatDate(role.endDate) : ""}
212→                        </span>
213→                      )}
214→                      {role.months > 0 && (
215→                        <span className="text-[11px] font-medium text-emerald-600 dark:text-emerald-400">
216→                          {formatDuration(role.months)}
217→                        </span>
218→                      )}
219→                    </div>
220→                    {role.relevance !== "low_relevance" && (
221→                      <Badge variant="outline" className={`text-[11px] mt-0.5 ${rel.cls}`}>
222→                        {rel.label}
223→                      </Badge>
224→                    )}
225→                    {role.relevance === "low_relevance" && (
226→                      <span className="text-[11px] text-muted-foreground/60">Low Relevance</span>
227→                    )}
228→                  </div>
229→                </div>
230→
231→                {/* Career gap flag */}
232→                {gap && (
233→                  <div className="flex items-center gap-2 pl-4 py-1">
234→                    <div className="flex-1 h-px bg-amber-300 dark:bg-amber-700" />
235→                    <span className="text-[11px] font-medium text-amber-600 dark:text-amber-400 bg-amber-500/10 px-2 py-0.5 rounded-full border border-amber-200 dark:border-amber-800">
236→                      {gap.months} mo gap
237→                    </span>
238→                    <div className="flex-1 h-px bg-amber-300 dark:bg-amber-700" />
239→                  </div>
240→                )}
241→              </div>
242→            );
243→          })}
244→        </div>
245→      ) : (
246→        <p className="text-xs text-muted-foreground">No experience data available</p>
247→      )}
248→
249→      {/* Footer */}
250→      {parsed.length > 0 && (
251→        <div className="flex items-center justify-between pt-1 border-t border-border">
252→          <span className="text-[11px] text-muted-foreground">
253→            {parsed.length} role{parsed.length !== 1 ? "s" : ""}
254→            {gaps.length > 0 ? ` · ${gaps.length} gap${gaps.length !== 1 ? "s" : ""}` : ""}
255→          </span>
256→          {parsed.length > 4 && (
257→            <Button
258→              variant="ghost"
259→              size="sm"
260→              className="h-6 px-2 text-[11px] text-muted-foreground hover:text-foreground gap-1"
261→              onClick={() => setShowDetail(!showDetail)}
262→            >
263→              {showDetail ? "Show less" : "See full detail"}
264→              {showDetail ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
265→            </Button>
266→          )}
267→        </div>
268→      )}
269→    </div>
270→  );
271→};
272→
273→export default ExperiencePanel;
274→
